#define NUMBER_OF_FIXED_POINTS 7

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; 

    float radius = 0.6;
    float pointRadius = 0.05;

    vec3 backgroundColor = vec3(0.5, 0.5, 0.5);

    vec2 points[NUMBER_OF_FIXED_POINTS];
    for (int i = 0; i < NUMBER_OF_FIXED_POINTS; i++)
    {
        float angle = float(i) * 6.28318530718 / float(NUMBER_OF_FIXED_POINTS); // Divide circle evenly
        points[i] = vec2(cos(angle), sin(angle)); 
    }

    vec3 color = backgroundColor;

    float dist = length(uv);

    // Check if inside the circle
    if (dist <= radius)
    {

        for (int i = 0; i < NUMBER_OF_FIXED_POINTS; i++)
        {
            float pointDist = length(uv - points[i] * radius);
            if (pointDist < pointRadius)
            {
                color = vec3(1.0, 1.0, 1.0); 
                break;
            }
        }

        if (color == backgroundColor)
        {
            float angle = atan(uv.y, uv.x); 
            if (angle < 0.0) angle += 6.28318530718; // Convert to [0, 2*PI]
            float segmentAngle = 6.28318530718 / float(NUMBER_OF_FIXED_POINTS); // Divide by the number of points
            int segmentIndex = int(angle / segmentAngle);

            // Assign segment color based on index
            color = vec3(float(segmentIndex) / float(NUMBER_OF_FIXED_POINTS), 1.0 - float(segmentIndex) / float(NUMBER_OF_FIXED_POINTS), 0.5);
        }
    }

    fragColor = vec4(color, 1.0);
}
